import java.io.*;import java.util.*;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine());if (n <= 2) {System.out.println(n);return;}long[] x = new long[n];long[] h = new long[n];for (int i = 0; i < n; i++) {StringTokenizer st = new StringTokenizer(br.readLine());x[i] = Long.parseLong(st.nextToken());h[i] = Long.parseLong(st.nextToken());}int count = 2;long lastPos = x[0];for (int i = 1; i < n - 1; i++) {if (x[i] - h[i] > lastPos) {count++;lastPos = x[i];} else if (x[i] + h[i] < x[i + 1]) {count++;lastPos = x[i] + h[i];} else {lastPos = x[i];}}System.out.println(count);}}